package com.asmj.marketplace.advertising;
import java.time.Instant; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document;
@Document("advertising_settings") public class AdvertisingSettings { @Id private String id="default"; private String upiId=""; private String payeeName="ASMJ Shoppe"; private String qrImageUrl=""; private boolean enabled=true; private Instant updatedAt=Instant.now(); public String getId(){return id;} public void setId(String v){id=v;} public String getUpiId(){return upiId;} public void setUpiId(String v){upiId=v;} public String getPayeeName(){return payeeName;} public void setPayeeName(String v){payeeName=v;} public String getQrImageUrl(){return qrImageUrl;} public void setQrImageUrl(String v){qrImageUrl=v;} public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} public Instant getUpdatedAt(){return updatedAt;} public void setUpdatedAt(Instant v){updatedAt=v;} }
